import { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../../contexts/AuthContext';
import axios from 'axios';
import { BarChart3, Image as ImageIcon, FileTerminal, LogOut } from 'lucide-react';
import QRCode from 'qrcode.react';

export default function Dashboard() {
  const { logout } = useContext(AuthContext);
  const [activeTab, setActiveTab] = useState('METRICS'); // METRICS, PHOTOS, LOGS

  const [metrics, setMetrics] = useState({ totalPhotos: 0, filteredPhotos: 0 });
  const [photos, setPhotos] = useState([]);
  const [logs, setLogs] = useState([]);
  const [selectedPhoto, setSelectedPhoto] = useState(null);

  useEffect(() => {
    fetchData();
  }, [activeTab]);

  const fetchData = async () => {
    try {
      if (activeTab === 'METRICS') {
        const { data } = await axios.get('http://localhost:5000/api/admin/metrics');
        setMetrics(data);
      } else if (activeTab === 'PHOTOS') {
        // Implement pagination here conceptually
        const { data } = await axios.get('http://localhost:5000/api/admin/photos?limit=24');
        setPhotos(data.photos);
      } else if (activeTab === 'LOGS') {
        const { data } = await axios.get('http://localhost:5000/api/admin/logs');
        setLogs(data);
      }
    } catch (error) {
      console.error('Fetch error:', error);
    }
  };

  const Sidebar = () => (
    <div className="w-64 bg-zinc-900 h-screen border-r border-zinc-800 flex flex-col">
      <div className="p-6">
        <h1 className="text-2xl font-black text-white tracking-tighter">NEX.admin</h1>
      </div>
      <nav className="flex-1 px-4 space-y-2">
        <button 
          onClick={() => setActiveTab('METRICS')}
          className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-colors ${activeTab === 'METRICS' ? 'bg-brand-accent text-white' : 'text-zinc-400 hover:bg-zinc-800 hover:text-white'}`}
        >
          <BarChart3 size={20} /> Métricas
        </button>
        <button 
          onClick={() => setActiveTab('PHOTOS')}
          className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-colors ${activeTab === 'PHOTOS' ? 'bg-brand-accent text-white' : 'text-zinc-400 hover:bg-zinc-800 hover:text-white'}`}
        >
          <ImageIcon size={20} /> Fotos
        </button>
        <button 
          onClick={() => setActiveTab('LOGS')}
          className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-colors ${activeTab === 'LOGS' ? 'bg-brand-accent text-white' : 'text-zinc-400 hover:bg-zinc-800 hover:text-white'}`}
        >
          <FileTerminal size={20} /> Logs do Sistema
        </button>
      </nav>
      <div className="p-4 border-t border-zinc-800">
        <button 
          onClick={logout}
          className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-red-500 hover:bg-red-500/10 transition-colors"
        >
          <LogOut size={20} /> Sair
        </button>
      </div>
    </div>
  );

  return (
    <div className="flex min-h-screen bg-brand-dark text-white">
      <Sidebar />
      <main className="flex-1 p-8 h-screen overflow-y-auto">

        {activeTab === 'METRICS' && (
          <div className="space-y-6 animate-in fade-in">
            <h2 className="text-3xl font-bold">Visão Geral</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-2xl flex flex-col justify-between h-40">
                <span className="text-zinc-400 font-medium">Fotos Totais</span>
                <span className="text-6xl font-black">{metrics.totalPhotos}</span>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'PHOTOS' && (
          <div className="space-y-6 animate-in fade-in">
            <h2 className="text-3xl font-bold">Galeria</h2>
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
              {photos.map(photo => (
                <div 
                  key={photo._id} 
                  className="bg-zinc-900 border border-zinc-800 rounded-xl overflow-hidden cursor-pointer hover:ring-2 ring-brand-accent transition-all group"
                  onClick={() => setSelectedPhoto(photo)}
                >
                  <img src={photo.url} alt="User capture" className="w-full aspect-[9/16] object-cover group-hover:scale-105 transition-transform duration-500" />
                </div>
              ))}
            </div>
            {photos.length === 0 && <p className="text-zinc-500 text-center py-20">Nenhuma foto encontrada.</p>}
          </div>
        )}

        {activeTab === 'LOGS' && (
          <div className="space-y-6 animate-in fade-in">
            <div className="flex justify-between items-center">
              <h2 className="text-3xl font-bold">Logs do Sistema</h2>
              <button className="bg-zinc-800 hover:bg-zinc-700 text-white px-4 py-2 rounded-lg text-sm transition-colors border border-zinc-700">
                Exportar CSV
              </button>
            </div>
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl overflow-hidden">
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-zinc-800/50 uppercase text-zinc-400">
                  <tr>
                    <th className="px-6 py-4">Data/Hora</th>
                    <th className="px-6 py-4">IP Mascarado</th>
                    <th className="px-6 py-4">Rota</th>
                    <th className="px-6 py-4">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-zinc-800">
                  {logs.map(log => (
                    <tr key={log._id} className="hover:bg-zinc-800/30">
                      <td className="px-6 py-4 text-zinc-300">{new Date(log.timestamp).toLocaleString('pt-BR')}</td>
                      <td className="px-6 py-4 font-mono text-zinc-400">{log.masked_ip}</td>
                      <td className="px-6 py-4 font-mono text-brand-accent">{log.route}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded-md text-xs font-bold ${log.response_status < 400 ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                          {log.response_status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {logs.length === 0 && <p className="text-zinc-500 text-center py-10">Nenhum log encontrado.</p>}
            </div>
          </div>
        )}

      </main>

      {/* Photo Modal */}
      {selectedPhoto && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center p-8 z-50 transition-opacity" onClick={() => setSelectedPhoto(null)}>
          <div className="bg-zinc-900 border border-zinc-800 rounded-3xl p-8 flex gap-8 max-w-5xl w-full" onClick={e => e.stopPropagation()}>
            <img src={selectedPhoto.url} className="h-[70vh] rounded-xl object-contain bg-black shadow-2xl" />
            <div className="flex flex-col justify-center gap-8 border-l border-zinc-800 pl-8">
              <div>
                <h3 className="text-xl font-bold mb-2">Detalhes</h3>
                <p className="text-zinc-400 text-sm">Data: {new Date(selectedPhoto.createdAt).toLocaleString('pt-BR')}</p>
                <div className="mt-4">
                  <a href={selectedPhoto.url} target="_blank" className="text-brand-accent hover:underline text-sm font-medium">Abrir imagem original</a>
                </div>
              </div>
              <div className="bg-white p-6 rounded-2xl w-max self-start shadow-xl">
                <QRCode value={selectedPhoto.url} size={200} />
              </div>
            </div>
            <button 
              className="absolute top-8 right-8 w-12 h-12 bg-zinc-800 hover:bg-zinc-700 rounded-full flex items-center justify-center transition-colors"
              onClick={() => setSelectedPhoto(null)}
            >
              <LogOut size={20} className="rotate-45" /> {/* simple cross icon approximation */}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
